import itertools

def solve():
    # Read H, W, D
    line1 = input().split()
    if not line1: return
    H, W, D = map(int, line1)

    # Read the grid
    grid = [input() for _ in range(H)]

    # Identify all floor cells (i, j)
    floors = [
        (i, j) 
        for i in range(H) 
        for j in range(W) 
        if grid[i][j] == '.'
    ]

    # Pre-calculate which floor cells are covered by a humidifier at (r, c)
    # coverage[idx] is a set of floor indices covered by humidifier at floors[idx]
    coverage = [
        {
            target_idx 
            for target_idx, (tr, tc) in enumerate(floors) 
            if abs(r - tr) + abs(c - tc) <= D
        } 
        for (r, c) in floors
    ]

    # Try all combinations of 2 distinct floor cells
    # The result is the size of the union of their coverage sets
    ans = max(
        len(coverage[i] | coverage[j]) 
        for i, j in itertools.combinations(range(len(floors)), 2)
    )

    print(ans)

if __name__ == "__main__":
    solve()
